const item = $input.item.json;

// --- STEP 1: FIND THE DATA ---
// Check if data is at the top level OR inside body.result
let data = item;
if (item.body && item.body.result) {
    data = item.body.result;
}

// --- STEP 2: DEFINE EXTRACTION FUNCTION ---
const getDomain = (emailStr) => {
  // 1. Safety Check: Is it empty?
  if (!emailStr || typeof emailStr !== 'string') return null;

  // 2. Regex: Find anything that looks like user@domain.com
  const match = emailStr.match(/([a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z0-9._-]+)/);

  // 3. Extract the domain part (after the @)
  if (match && match[1]) {
      return match[1].split('@')[1];
  }
  return null;
};

// --- STEP 3: EXTRACT DOMAINS ---
// We read from the 'data' variable we found in Step 1
const fromDomain = getDomain(data.from);
const returnDomain = getDomain(data.return_path);
const replyDomain = getDomain(data.reply_to);

// --- STEP 4: DECISION LOGIC ---
let domainToScan = fromDomain; // Default
let scanReason = "Standard Sender Check (From)";

// Priority 1: Reply-To Mismatch
if (data.is_bad_reply === "true" && replyDomain) {
    domainToScan = replyDomain;
    scanReason = "Suspicious Reply-To Mismatch";
} 
// Priority 2: Spoofing
else if (data.is_spoof === "true" && returnDomain) {
    domainToScan = returnDomain;
    scanReason = "Spoofed Origin (Return-Path)";
}

// --- STEP 5: OUTPUT ---
return {
    json: {
        domain_for_vt: domainToScan,
        scan_reason: scanReason,
        // Debugging (Should show values now!)
        debug_found_data_at: (item.body && item.body.result) ? "body.result" : "root",
        debug_raw_reply: data.reply_to,
        ...data // Return the flattened data so next nodes can see it easily
    }
}

