// LIST OF YOUR PARSE NODES
// As you add Path 3, Path 4, just add their names here.
const possibleSources = [
  'Parse GPT JSON',     // Path 1
  'Parse GPT JSON2',
  'Parse GPT JSON3'
];

let slackMsg = "⚠️ Alert Details Missing";
let severity = "High";

// LOOP TO FIND THE ACTIVE PATH
for (const nodeName of possibleSources) {
  try {
    // We try to grab the output of the node.
    // If the node didn't run, n8n throws an error, which we catch and ignore.
    const nodeData = $(nodeName).first().json;

    if (nodeData && nodeData.slack_message) {
      slackMsg = nodeData.slack_message;
      severity = nodeData.severity_label;
      break; // Found it! Stop looking.
    }
  } catch (error) {
    // This path didn't run, so check the next one.
    continue;
  }
}

// MERGE WITH JIRA TICKET INFO
const jiraData = $input.item.json;

return {
    json: {
        slack_message: slackMsg,
        severity_label: severity,
        ...jiraData // Contains key, id, self
    }
};

